head.script:
scwin.getType = function(info) {
	var rowIdx = info.rowIndex;
	var colIdx = info.colIndex;
	var status = grd_result_file.getRowStatus(rowIdx);
	var result = {};
	result.id = "random_" + status + "_" + rowIdx + "_" + colIdx;
	result.inputType = "textImage";
	if (status == "C") {
		result.options = {viewType: "icon", imageSrc: "/img/gridView_custom_txtImg_imgClickFunc_WAEA-237_(WSQ-5982).svg", imageWidth: "26", imageHeight: "26", imageClickFunction: "scwin.ff_CustSearchPop(" + info.rowIndex + ")"};
		grd_result_file.setCellClass(rowIdx, colIdx, "req");
	} else {
		result.options = {};
	}
	grd_result_file.setReadOnly("cell", rowIdx, colIdx, true);
	return result;
};

scwin.ff_CustSearchPop = async function(nRow) {
	window.checkLog = "scwin.ff_CustSearchPop event...." + nRow;
};

scwin.onpageload = function() {
	window.checkLog = "";
};

scwin.trigger1_onclick = function(e) {
	var nRow = dataList1.insertRow();
	dataList1.setCellData(nRow, "s_checkbox", "1");
	dataList1.setCellData(nRow, "bondBsnsClCd", "301");
};

scwin.checkVal1 = function() {
	return window.checkLog == "";
};

scwin.initCheckVal = function() {
	window.checkLog = "";
};

scwin.checkVal2 = function() {
	return window.checkLog == "scwin.ff_CustSearchPop event....0";
};
